messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Race</title>
    <style>
        body { margin: 0; overflow: hidden; background: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB);
    scene.fog = new THREE.Fog(0x87CEEB, 10, 150);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
    camera.position.set(0, 5, -12);
    camera.lookAt(0, 0, 10);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambient);
    const sun = new THREE.DirectionalLight(0xffffff, 1);
    sun.position.set(10, 20, -10);
    sun.castShadow = true;
    sun.shadow.camera.left = -20;
    sun.shadow.camera.right = 20;
    sun.shadow.camera.top = 20;
    sun.shadow.camera.bottom = -20;
    scene.add(sun);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(200, 400);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Finish Line
    const lineGeo = new THREE.PlaneGeometry(14, 2);
    const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const finishLine = new THREE.Mesh(lineGeo, lineMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.set(0, 0.01, 80);
    scene.add(finishLine);

    // Car Factory
    function createCar(color) {
        const group = new THREE.Group();

        const body = new THREE.Mesh(
            new THREE.BoxGeometry(1.8, 0.8, 3.5),
            new THREE.MeshStandardMaterial({ color })
        );
        body.position.y = 0.6;
        body.castShadow = true;
        group.add(body);

        const cabin = new THREE.Mesh(
            new THREE.BoxGeometry(1.4, 0.6, 1.5),
            new THREE.MeshStandardMaterial({ color: 0x111111 })
        );
        cabin.position.y = 1.2;
        cabin.position.z = -0.2;
        cabin.castShadow = true;
        group.add(cabin);

        const wheelGeo = new THREE.CylinderGeometry(0.35, 0.35, 0.2, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x000000 });

        const positions = [
            [-0.9, 0.35, 1.2], [0.9, 0.35, 1.2],
            [-0.9, 0.35, -1.2], [0.9, 0.35, -1.2]
        ];

        positions.forEach(pos => {
            const w = new THREE.Mesh(wheelGeo, wheelMat);
            w.rotation.z = Math.PI / 2;
            w.position.set(...pos);
            w.castShadow = true;
            group.add(w);
        });

        return group;
    }

    const blueCar = createCar(0x0000ff);
    blueCar.position.set(-3, 0, 0);
    scene.add(blueCar);

    const redCar = createCar(0xff0000);
    redCar.position.set(3, 0, 0);
    scene.add(redCar);

    // Race Logic
    const finishZ = 80;
    const raceDuration = 6000; // ms
    let raceStart = Date.now();

    function getPos(t) {
        // t is 0 to 1
        // Blue: starts fast, slows down. 0.8 at 0.5, 1.0 at 1.0
        if (t < 0.5) return (t / 0.5) * 0.8;
        return 0.8 + ((t - 0.5) / 0.5) * 0.2;
    }

    function getPosRed(t) {
        // t is 0 to 1
        // Red: starts slow, accelerates. 0.4 at 0.5, 1.1 at 1.0
        if (t < 0.5) return (t / 0.5) * 0.4;
        return 0.4 + ((t - 0.5) / 0.5) * 0.7;
    }

    function animate() {
        requestAnimationFrame(animate);

        const now = Date.now();
        let elapsed = (now - raceStart) % raceDuration;
        let t = elapsed / raceDuration;

        // Reset if looped
        if (now - raceStart > raceDuration) raceStart = now;

        // Move cars
        blueCar.position.z = getPos(t) * finishZ;
        redCar.position.z = getPosRed(t) * finishZ;

        // Camera follows
        const avgZ = (blueCar.position.z + redCar.position.z) / 2;
        camera.position.z = avgZ - 10;
        camera.lookAt(0, 0, avgZ + 10);

        renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });
</script>
</body>
</html>
```
